<style>
.customer-dashboard-body{color:#172033}.customer-dashboard-content{min-height:calc(100vh - 142px)}
.customer-page-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:24px}.customer-page-heading>div:first-child>span,.customer-panel-heading>div>span,.customer-form-card>header>span{display:block;margin-bottom:6px;color:#0f766e;font-size:11px;font-weight:900;letter-spacing:.11em;text-transform:uppercase}.customer-page-heading h2{margin:0;color:#172033;font-size:30px;line-height:1.2}.customer-page-heading p{margin:7px 0 0;color:#64748b;font-size:14px;line-height:1.6}
.customer-primary-button,.customer-heading-actions a{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px;padding:0 15px;border-radius:9px;background:#172033;color:#fff;font-size:13px;font-weight:850;text-decoration:none}.customer-heading-actions{display:flex;flex-wrap:wrap;gap:9px}.customer-heading-actions a.secondary{border:1px solid #cbd5e1;background:#fff;color:#334155}
.customer-stat-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:22px}.customer-stat-card{display:flex;align-items:center;gap:15px;padding:20px;border:1px solid #e5eaf1;border-radius:14px;background:#fff;box-shadow:0 8px 24px rgba(15,23,42,.04)}.customer-stat-icon{display:grid;flex:0 0 46px;width:46px;height:46px;place-items:center;border-radius:12px;background:#dbeafe;color:#1d4ed8;font-size:18px}.customer-stat-icon.amber{background:#fef3c7;color:#b45309}.customer-stat-icon.violet{background:#ede9fe;color:#7c3aed}.customer-stat-icon.green{background:#d1fae5;color:#047857}.customer-stat-card small,.customer-stat-card strong,.customer-stat-card p{display:block}.customer-stat-card small{color:#64748b;font-size:11px;font-weight:800;text-transform:uppercase}.customer-stat-card strong{margin-top:2px;color:#172033;font-size:25px}.customer-stat-card p{margin:2px 0 0;color:#94a3b8;font-size:11px}
.customer-panel{overflow:hidden;border:1px solid #e5eaf1;border-radius:14px;background:#fff;box-shadow:0 8px 24px rgba(15,23,42,.035)}.customer-panel-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 20px;border-bottom:1px solid #edf0f5}.customer-panel-heading h3{margin:0;color:#172033;font-size:17px}.customer-panel-heading a{color:#0f766e;font-size:12px;font-weight:850;text-decoration:none}.customer-table-wrap{overflow-x:auto}.customer-table{width:100%;min-width:760px;border-collapse:collapse}.customer-table th{padding:11px 16px;background:#f8fafc;color:#64748b;font-size:10px;font-weight:850;letter-spacing:.08em;text-align:left;text-transform:uppercase}.customer-table td{padding:15px 16px;border-top:1px solid #edf0f5;color:#475569;font-size:13px}.customer-table tbody tr:hover{background:#fafcfe}.customer-table td strong,.customer-table td small{display:block}.customer-table td strong{color:#172033}.customer-table td small{margin-top:4px;color:#94a3b8}.customer-status{display:inline-flex;padding:6px 9px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:9px;font-weight:900;letter-spacing:.03em;text-transform:uppercase}.customer-status.processing,.customer-status.shipped{background:#dbeafe;color:#1d4ed8}.customer-status.completed,.customer-status.delivered,.customer-status.paid,.customer-status.succeeded{background:#d1fae5;color:#047857}.customer-status.cancelled,.customer-status.refunded,.customer-status.failed{background:#ffe4e6;color:#be123c}.customer-row-action{display:inline-flex;align-items:center;gap:7px;color:#0f766e;font-size:12px;font-weight:850;text-decoration:none}.customer-empty{padding:55px 20px;text-align:center}.customer-empty>span{display:grid;width:54px;height:54px;margin:auto;place-items:center;border-radius:15px;background:#f1f5f9;color:#64748b;font-size:22px}.customer-empty h3{margin:13px 0 5px}.customer-empty p{margin:0 0 15px;color:#64748b}.customer-empty a{color:#0f766e;font-weight:850;text-decoration:none}
.customer-filters{display:flex;align-items:flex-end;gap:10px;padding:18px 20px;border-bottom:1px solid #edf0f5}.customer-filters label{display:grid;flex:1;gap:6px}.customer-filters label span,.customer-field>span{color:#475569;font-size:11px;font-weight:850}.customer-filters input,.customer-filters select,.customer-field input{width:100%;min-height:42px;box-sizing:border-box;padding:9px 11px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#172033;font:inherit}.customer-filters button,.customer-filters>a{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:42px;padding:0 14px;border:0;border-radius:8px;background:#172033;color:#fff;font-size:12px;font-weight:850;text-decoration:none;cursor:pointer}.customer-filters>a{background:#f1f5f9;color:#475569}.customer-pagination{padding:16px 20px}
.customer-order-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,1fr);gap:18px}.customer-totals{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:18px}.customer-totals>div{padding:13px;border-radius:10px;background:#f8fafc}.customer-totals small,.customer-totals strong{display:block}.customer-totals small{color:#64748b;font-size:11px}.customer-totals strong{margin-top:4px;font-size:13px}.customer-totals .grand-total{background:#172033;color:#fff}.customer-totals .grand-total small{color:#cbd5e1}.customer-delivery-card{align-self:start}.customer-address{display:flex;gap:12px;padding:20px;border-bottom:1px solid #edf0f5}.customer-address-icon{display:grid;flex:0 0 38px;width:38px;height:38px;place-items:center;border-radius:10px;background:#ecfdf5;color:#047857}.customer-address p{margin:0;color:#64748b;font-size:13px;line-height:1.7}.customer-address strong{color:#172033}.customer-detail-list{margin:0;padding:8px 20px}.customer-detail-list>div{display:flex;justify-content:space-between;gap:15px;padding:11px 0;border-bottom:1px solid #edf0f5}.customer-detail-list dt{color:#64748b;font-size:12px}.customer-detail-list dd{margin:0;color:#172033;font-size:12px;font-weight:800;text-align:right}.customer-order-updates{padding:5px 20px 18px}.customer-order-updates h4{margin:12px 0}.customer-order-updates p{padding:10px;border-radius:8px;background:#f8fafc;color:#64748b;font-size:12px;line-height:1.6}
.customer-profile-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.customer-form-card{padding:22px}.customer-form-card.danger{grid-column:1/-1}.customer-form-card>header{margin-bottom:18px}.customer-form-card h3{margin:0;font-size:18px}.customer-form-card header p{margin:6px 0 0;color:#64748b;font-size:13px;line-height:1.6}.customer-field{display:grid;gap:6px;margin-bottom:14px}.customer-field small{color:#be123c;font-size:11px}.customer-form-actions{display:flex;align-items:center;gap:12px}.customer-form-actions button,.customer-delete-account button{min-height:41px;padding:0 14px;border:0;border-radius:8px;background:#172033;color:#fff;font-weight:850;cursor:pointer}.customer-form-actions em{color:#047857;font-size:12px;font-style:normal;font-weight:800}.customer-delete-account summary{display:inline-flex;padding:10px 14px;border-radius:8px;background:#ffe4e6;color:#be123c;font-size:12px;font-weight:850;cursor:pointer}.customer-delete-account form{max-width:520px;margin-top:16px;padding:16px;border-radius:10px;background:#fff7f7}.customer-delete-account form p{color:#64748b;font-size:13px}.customer-delete-account button{background:#be123c}
@media(max-width:1100px){.customer-stat-grid{grid-template-columns:repeat(2,1fr)}.customer-order-grid{grid-template-columns:1fr}.customer-delivery-card{align-self:stretch}}@media(max-width:760px){.customer-page-heading{align-items:flex-start;flex-direction:column}.customer-stat-grid,.customer-profile-grid{grid-template-columns:1fr}.customer-form-card.danger{grid-column:auto}.customer-filters{align-items:stretch;flex-direction:column}.customer-filters label,.customer-filters button,.customer-filters>a{width:100%}.customer-totals{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.customer-stat-grid,.customer-totals{grid-template-columns:1fr}.customer-heading-actions{width:100%}.customer-heading-actions a{flex:1}}
</style>
